<script setup lang="ts">
import{onMounted,reactive,ref}from'vue'
import{actualizarConfiguracion,crearConfiguracion,eliminarConfiguracion,listarConfiguraciones,type Configuracion,type ConfiguracionFilters,type ConfiguracionPayload,type TipoDato}from'../services/configuracionSistema'

const rows=ref<Configuracion[]>([]),categories=ref<string[]>([]),total=ref(0),last=ref(1),loading=ref(false),saving=ref(false),modal=ref(false),editing=ref<Configuracion|null>(null),error=ref(''),success=ref('')
const filters=reactive<ConfiguracionFilters>({criterio:'',categoria:'',page:1})
const empty=():ConfiguracionPayload=>({codigo:'',valor:'',descripcion:'',tipo_dato:'string',categoria:'',es_editable:true,orden:0}),form=reactive<ConfiguracionPayload>(empty())
async function load(page=1){filters.page=page;loading.value=true;error.value='';try{const result=await listarConfiguraciones(filters);rows.value=result.data;categories.value=result.categorias;total.value=result.total;last.value=result.last_page}catch(e){error.value=message(e)}finally{loading.value=false}}
function clear(){Object.assign(filters,{criterio:'',categoria:'',page:1});load()}
function open(row?:Configuracion){editing.value=row||null;Object.assign(form,row?{codigo:row.codigo,valor:row.valor,descripcion:row.descripcion||'',tipo_dato:row.tipo_dato,categoria:row.categoria||'',es_editable:row.es_editable,orden:row.orden}:empty());modal.value=true;error.value=''}
function validate(){form.codigo=form.codigo.trim().toUpperCase();if(!form.codigo||!form.valor.trim())return'Complete el código y el valor.';if(form.codigo.length>100)return'El código no puede superar 100 caracteres.';if(form.categoria.length>50)return'La categoría no puede superar 50 caracteres.';if(form.orden<0)return'El orden no puede ser negativo.';if(form.tipo_dato==='integer'&&!/^-?\d+$/.test(form.valor.trim()))return'El valor debe ser un número entero.';if(form.tipo_dato==='decimal'&&!/^-?\d+(\.\d+)?$/.test(form.valor.trim()))return'El valor debe ser un número decimal válido.';if(form.tipo_dato==='boolean'&&!['0','1'].includes(form.valor))return'Seleccione Sí o No para el valor booleano.';if(form.tipo_dato==='json'){try{JSON.parse(form.valor)}catch{return'El valor no contiene un JSON válido.'}}return''}
async function save(){const issue=validate();if(issue){error.value=issue;return}saving.value=true;error.value='';try{editing.value?await actualizarConfiguracion(editing.value.id,{...form}):await crearConfiguracion({...form});success.value=editing.value?'Configuración actualizada correctamente.':'Configuración registrada correctamente.';modal.value=false;await load(editing.value?filters.page:1)}catch(e){error.value=message(e)}finally{saving.value=false}}
async function remove(row:Configuracion){if(!row.es_editable||!confirm(`¿Eliminar la configuración ${row.codigo}?`))return;error.value='';try{await eliminarConfiguracion(row.id);success.value='Configuración eliminada correctamente.';await load(rows.value.length===1&&filters.page>1?filters.page-1:filters.page)}catch(e){error.value=message(e)}}
function typeName(type:TipoDato){return({string:'Texto',integer:'Entero',boolean:'Booleano',decimal:'Decimal',json:'JSON'} as Record<TipoDato,string>)[type]}
function display(row:Configuracion){if(row.tipo_dato==='boolean')return row.valor==='1'?'Sí':'No';return row.valor.length>65?`${row.valor.slice(0,65)}…`:row.valor}
function message(e:unknown){return e instanceof Error?e.message:'No se pudo completar la operación.'}
onMounted(()=>load())
</script>

<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Sistema / Administrador / Configuración</nav><header class="hero"><div class="mark">CF</div><div><small>ADMINISTRACIÓN GENERAL</small><h1>Configuración del sistema</h1><p>Parámetros operativos de la empresa activa.</p></div><strong>{{total}} parámetros</strong><button @click="open()">+ Nueva configuración</button></header><div v-if="success" class="flash good">✓ {{success}}</div><div v-if="error" class="flash bad">{{error}}</div><section class="filters"><label>Buscar<input v-model.trim="filters.criterio" placeholder="Código, descripción o categoría" @keyup.enter="load()"></label><label>Categoría<select v-model="filters.categoria"><option value="">Todas las categorías</option><option v-for="category in categories" :key="category">{{category}}</option></select></label><button @click="load()">Buscar</button><button class="clear" @click="clear">Limpiar</button></section><div v-if="loading" class="empty">Cargando configuraciones…</div><div v-else-if="!rows.length" class="empty">No se encontraron configuraciones.</div><section v-else class="table"><header><span>Código / descripción</span><span>Valor</span><span>Tipo</span><span>Categoría</span><span>Orden</span><span>Acciones</span></header><article v-for="row in rows" :key="row.id"><div><code>{{row.codigo}}</code><small>{{row.descripcion||'Sin descripción'}}</small></div><b class="value">{{display(row)}}</b><span class="type">{{typeName(row.tipo_dato)}}</span><span>{{row.categoria||'—'}}</span><span>{{row.orden}}</span><div class="actions"><button @click="open(row)">{{row.es_editable?'Editar':'Ver'}}</button><button v-if="row.es_editable" class="delete" @click="remove(row)">Eliminar</button><span v-else>🔒 Protegido</span></div></article></section><footer v-if="last>1" class="pages"><button :disabled="filters.page<=1" @click="load(filters.page-1)">Anterior</button><span>Página {{filters.page}} de {{last}}</span><button :disabled="filters.page>=last" @click="load(filters.page+1)">Siguiente</button></footer><div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="modal" @submit.prevent="save"><header><div><small>{{editing?'EDITAR PARÁMETRO':'NUEVO PARÁMETRO'}}</small><h2>{{editing?.codigo||'Registrar configuración'}}</h2></div><button type="button" @click="modal=false">×</button></header><div class="grid"><label>Código *<input v-model="form.codigo" :disabled="!!editing&&!editing.es_editable" maxlength="100" placeholder="MAXIMO_TAMANIO_ARCHIVO_MB" @input="form.codigo=form.codigo.toUpperCase()"><small>Identificador único; se almacena en mayúsculas.</small></label><label>Tipo de dato *<select v-model="form.tipo_dato" :disabled="!!editing&&!editing.es_editable" @change="form.valor=form.tipo_dato==='boolean'?'1':''"><option value="string">Texto</option><option value="integer">Entero</option><option value="boolean">Booleano</option><option value="decimal">Decimal</option><option value="json">JSON</option></select></label><label>Categoría<input v-model.trim="form.categoria" :disabled="!!editing&&!editing.es_editable" maxlength="50" placeholder="archivos, documentos, email"></label><label>Orden<input v-model.number="form.orden" :disabled="!!editing&&!editing.es_editable" type="number" min="0"></label></div><label class="wide">Valor *<select v-if="form.tipo_dato==='boolean'" v-model="form.valor" :disabled="!!editing&&!editing.es_editable"><option value="1">Sí</option><option value="0">No</option></select><textarea v-else v-model="form.valor" :disabled="!!editing&&!editing.es_editable" rows="4" :placeholder="form.tipo_dato==='json'?'Ej. {&quot;clave&quot;: &quot;valor&quot;}':'Valor del parámetro'"></textarea></label><label class="wide">Descripción<textarea v-model.trim="form.descripcion" :disabled="!!editing&&!editing.es_editable" rows="2" placeholder="Explique para qué sirve este parámetro"></textarea></label><label class="check"><input v-model="form.es_editable" :disabled="!!editing&&!editing.es_editable" type="checkbox"> Parámetro editable desde la interfaz</label><p v-if="editing&&!editing.es_editable" class="locked">Este parámetro está protegido y se muestra únicamente para consulta.</p><footer><button type="button" class="clear" @click="modal=false">Cerrar</button><button v-if="!editing||editing.es_editable" :disabled="saving">{{saving?'Guardando…':'Guardar configuración'}}</button></footer></form></div></div></template>

<style scoped>
.page{--a:#334a61;color:#35444c}nav{margin-bottom:16px;color:#96a0a5;font-size:.7rem}nav a{color:var(--a)}.hero{padding:22px 25px;display:flex;align-items:center;gap:15px;border-left:5px solid var(--a);border-radius:13px;background:#fff}.mark{width:52px;height:52px;display:grid;place-items:center;border-radius:11px;color:#fff;background:var(--a);font-weight:800}.hero small,.modal small{color:var(--a);font-size:.52rem;font-weight:700}.hero h1{margin:2px 0;font-size:1.28rem}.hero p{margin:0;color:#7c898f;font-size:.62rem}.hero strong{margin-left:auto;font-size:.5rem}.hero button,.filters button,.pages button,.modal footer button{padding:8px 10px;border:0;border-radius:5px;color:#fff;background:var(--a);font-size:.47rem}.flash{padding:10px;font-size:.6rem}.good{color:#267359;background:#eaf8f1}.bad{color:#a13e43;background:#fff0f0}.filters{margin-top:12px;padding:12px;display:grid;grid-template-columns:1.5fr 1fr auto auto;align-items:end;gap:8px;background:#fff}.filters label{font-size:.47rem}input,select,textarea{width:100%;padding:8px;border:1px solid #d7e0e3;border-radius:5px;background:#fff;font:inherit;font-size:.5rem}textarea{resize:vertical}.clear{color:#68767c!important;background:#edf1f2!important}.table{margin-top:12px;background:#fff}.table>header,.table>article{padding:10px 12px;display:grid;grid-template-columns:1.5fr 1.4fr .65fr .7fr .35fr .85fr;align-items:center;gap:9px;border-bottom:1px solid #e9edee}.table>header{color:#849096;background:#f4f6f7;font-size:.42rem}.table article{font-size:.46rem}.table code{display:block;color:#31566e;font-size:.47rem;font-weight:700}.table small{display:block;color:#89949a;font-size:.4rem}.value{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.type{width:max-content;padding:4px 7px;border-radius:10px;color:#276b79;background:#e4f3f6;font-size:.39rem}.actions{display:flex;align-items:center;gap:5px}.actions button{border:0;color:var(--a);background:none;font-size:.43rem}.actions .delete{color:#a13e43}.actions span{color:#89949a;font-size:.38rem}.empty{margin-top:12px;padding:45px;text-align:center;background:#fff;font-size:.58rem}.pages{display:flex;justify-content:center;align-items:center;gap:10px;font-size:.48rem}.backdrop{position:fixed;z-index:100;inset:0;padding:16px;display:grid;place-items:center;background:#14283888}.modal{width:min(720px,100%);max-height:94vh;overflow:auto;padding:20px;border-radius:12px;background:#fff}.modal>header{display:flex}.modal h2{margin:2px 0;font-size:.9rem}.modal>header>button{margin-left:auto;border:0;background:none;font-size:1.4rem}.grid{margin-top:13px;display:grid;grid-template-columns:1.5fr 1fr;gap:9px}.modal label{display:block;margin-top:9px;font-size:.47rem}.modal label small{display:block;margin-top:3px;color:#89949a}.check{display:flex!important;align-items:center;gap:6px}.check input{width:auto}.locked{padding:9px;color:#8a6420;background:#fff4d8;font-size:.48rem}.modal footer{margin-top:15px;display:flex;justify-content:flex-end;gap:6px}@media(max-width:850px){.table>header{display:none}.table>article{grid-template-columns:1fr 1fr}.filters{grid-template-columns:1fr 1fr}}@media(max-width:540px){.hero{flex-wrap:wrap}.hero strong{margin-left:0}.filters,.grid,.table>article{grid-template-columns:1fr}}
</style>
